/**
 * Access to the scene sprite sheet (scene.png + scene.meta.ts, generated by scripts/sprites/scene.mjs):
 * wall and floor tiles, doors, arcade machines, crates, carried-item icons ...
 */
import sheetUrl from '../../assets/sprites/scene.png';
import { SCENE_SHEET, SCENE_SPRITES, SCENE_THEMES } from '../../assets/sprites/scene.meta';

export interface SceneSpriteDef {
  x: number;
  y: number;
  w: number;
  h: number;
  frames: number;
  fps: number;
}
export interface SceneTheme {
  wall: string;
  floor: string;
  decor: readonly string[];
}

export const SHEET_URL: string = sheetUrl;
export const SHEET: { w: number; h: number } = SCENE_SHEET;
export const SPRITES: Record<string, SceneSpriteDef> = SCENE_SPRITES;
export const THEMES: Record<string, SceneTheme> = SCENE_THEMES;

/* ---- repeating tiles: a CSS background cannot repeat a part of an atlas, so cut each tile out once ---- */
let sheetImage: Promise<HTMLImageElement> | null = null;
const tiles = new Map<string, Promise<string>>();

function loadSheet(): Promise<HTMLImageElement> {
  if (!sheetImage) {
    sheetImage = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = SHEET_URL;
    });
  }
  return sheetImage;
}

/** Data URL of one sprite (first frame) cut out of the sheet; '' when it does not exist. */
export function tileUrl(name: string): Promise<string> {
  const def = SPRITES[name];
  if (!def) return Promise.resolve('');
  let p = tiles.get(name);
  if (!p) {
    p = loadSheet()
      .then((img) => {
        const c = document.createElement('canvas');
        c.width = def.w;
        c.height = def.h;
        c.getContext('2d')?.drawImage(img, def.x, def.y, def.w, def.h, 0, 0, def.w, def.h);
        return c.toDataURL('image/png');
      })
      .catch(() => '');
    tiles.set(name, p);
  }
  return p;
}
